import { createExecutionErrorProjection } from "@hevy-mcp/core";
import {
	ApiError,
	HevyHttpError,
	isHevyHttpError,
	NetworkError,
	NotFoundError,
	RateLimitError,
	ValidationError,
} from "@hevy-mcp/hevy-client";
import {
	EmptyMeasurementUpdateError,
	PaginationMismatchError,
	TemplatesSearchValidationError,
	TrainingSummaryDataError,
	TrainingSummaryValidationError,
	WorkoutPayloadError,
	WorkoutPrivacyError,
} from "@hevy-mcp/operations";
import { ConfigurationError, UsageError } from "./arguments.js";

export class ApiResponseError extends Error {}

export const EXIT = { configuration: 1, usage: 2, api: 3, network: 4 } as const;

export interface CliDiagnostic {
	code: number;
	message: string;
	error_code?: string;
	outcome?: string;
	phase?: string;
	operation_safety?: string;
	commit_state?: string;
	safe_to_retry?: boolean;
}

type TaggedClientError =
	| ApiError
	| NetworkError
	| NotFoundError
	| RateLimitError
	| ValidationError;

type OperationDomainError =
	| EmptyMeasurementUpdateError
	| PaginationMismatchError
	| TemplatesSearchValidationError
	| TrainingSummaryDataError
	| TrainingSummaryValidationError
	| WorkoutPayloadError
	| WorkoutPrivacyError;

function isTaggedClientError(
	error: Error | string,
): error is TaggedClientError {
	return (
		error instanceof ApiError ||
		error instanceof NetworkError ||
		error instanceof NotFoundError ||
		error instanceof RateLimitError ||
		error instanceof ValidationError
	);
}

function isOperationDomainError(
	error: Error | string,
): error is OperationDomainError {
	return (
		error instanceof EmptyMeasurementUpdateError ||
		error instanceof TrainingSummaryDataError ||
		error instanceof PaginationMismatchError ||
		error instanceof TemplatesSearchValidationError ||
		error instanceof TrainingSummaryValidationError ||
		error instanceof WorkoutPayloadError ||
		error instanceof WorkoutPrivacyError
	);
}

function executionFields(
	error: Error | string,
): Omit<CliDiagnostic, "code" | "message"> {
	if (!isHevyHttpError(error) && !isTaggedClientError(error)) return {};
	const {
		status: _status,
		code: errorCode,
		...execution
	} = createExecutionErrorProjection(error);
	return errorCode === undefined
		? execution
		: { ...execution, error_code: errorCode };
}

export function diagnostic(error: Error | string): CliDiagnostic {
	if (error instanceof ConfigurationError)
		return { code: EXIT.configuration, message: error.message };
	if (error instanceof ApiResponseError)
		return {
			code: EXIT.api,
			message: error.message.replace(/https?:\/\/\S+/gi, "[redacted]"),
			...executionFields(error),
		};
	if (isOperationDomainError(error)) {
		if (
			error instanceof PaginationMismatchError ||
			error instanceof WorkoutPayloadError ||
			error instanceof TrainingSummaryDataError
		) {
			return {
				code: EXIT.api,
				message:
					error instanceof PaginationMismatchError
						? "The API returned invalid pagination metadata"
						: error.message,
			};
		}
		return { code: EXIT.usage, message: error.message };
	}
	if (
		error instanceof HevyHttpError ||
		isHevyHttpError(error) ||
		isTaggedClientError(error)
	) {
		const status = "status" in error ? error.status : undefined;
		if (status === 401)
			return {
				code: EXIT.api,
				message: "Authentication failed; check HEVY_API_KEY",
				...executionFields(error),
			};
		if (status !== undefined)
			return {
				code: EXIT.api,
				message: `Hevy API request failed (HTTP ${status})`,
				...executionFields(error),
			};
		return {
			code: EXIT.network,
			message:
				("code" in error ? error.code : undefined) === "ETIMEDOUT"
					? "Hevy API request timed out"
					: "Unable to reach the Hevy API",
			...executionFields(error),
		};
	}
	if (error instanceof UsageError)
		return {
			code: EXIT.usage,
			message: error.message.replace(/https?:\/\/\S+/gi, "[redacted]"),
		};
	return { code: EXIT.usage, message: "Command failed" };
}

import { readFile } from "node:fs/promises";
import { z } from "zod";
import { UsageError } from "./arguments.js";

export type DataSourceReader = (source: string) => Promise<string>;

async function readStdin(): Promise<string> {
	const chunks: Buffer[] = [];
	for await (const chunk of process.stdin) {
		chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk)));
	}
	return Buffer.concat(chunks).toString("utf8");
}

export const readDataSource: DataSourceReader = (source) =>
	source === "-" ? readStdin() : readFile(source, "utf8");

function schemaDiagnostic(error: z.ZodError): string {
	const issue = error.issues[0];
	const path = issue?.path.join(".");
	return path
		? `--data.${path} ${issue.message}`
		: `--data ${issue?.message ?? "is invalid"}`;
}

export async function loadMutationInput<T>(
	value: string,
	schema: z.ZodType<T>,
	reader: DataSourceReader = readDataSource,
): Promise<T> {
	let sourceValue = value;
	if (value.startsWith("@")) {
		const source = value.slice(1);
		if (source.length === 0)
			throw new UsageError("--data source is required after @");
		try {
			sourceValue = await reader(source);
		} catch {
			throw new UsageError(`Unable to read --data source "${source}"`);
		}
	}

	let parsed: unknown;
	try {
		parsed = JSON.parse(sourceValue);
	} catch {
		throw new UsageError("--data must contain valid JSON");
	}

	try {
		return schema.parse(parsed);
	} catch (error) {
		if (error instanceof z.ZodError)
			throw new UsageError(schemaDiagnostic(error));
		throw error;
	}
}

