		const json = (value: JsonObject) => JSON.stringify(value);
		const commands = [
			["workouts", "create", "--data", json(workout), "--yes", "--json"],
			[
				"workouts",
				"update",
				"workout-1",
				"--data",
				json({ workout_id: "workout-1", ...workout }),
				"--yes",
				"--json",
			],
			["routines", "create", "--data", json(routine), "--yes", "--json"],
			[
				"routines",
				"update",
				"routine-1",
				"--data",
				json({ routine_id: "routine-1", ...routine }),
				"--yes",
				"--json",
			],
			[
				"exercises",
				"create",
				"--data",
				json({
					exercise: {
						title: "Cable Row",
