						equipment_category: "machine",
						muscle_group: "upper_back",
					},
				}),
				"--yes",
				"--json",
			],
			[
				"folders",
				"create",
				"--data",
				json({ routine_folder: { title: "Strength" } }),
				"--yes",
				"--json",
			],
			[
				"measurements",
