		},
	);
});

describe("CLI JSON error_code compatibility", () => {
	const errorCases = [
		[
			"ApiError",
			new ApiError({
				status: 500,
				endpoint: "/v1/workouts",
				method: "GET",
				code: "HEVY_RETRY_EXHAUSTED",
			}),
			"HEVY_RETRY_EXHAUSTED",
			3,
		],
		[
			"NetworkError",
			new NetworkError({
				code: "ERR_NETWORK",
				endpoint: "/v1/workouts",
				method: "GET",
				retryExhausted: false,
			}),
			"ERR_NETWORK",
			4,
		],
		[
			"NotFoundError",
			new NotFoundError({
				status: 404,
				endpoint: "/v1/workouts/:workoutId",
				method: "GET",
				expected: false,
			}),
			undefined,
			3,
		],
		[
			"RateLimitError",
			new RateLimitError({
				status: 429,
				endpoint: "/v1/workouts",
				method: "GET",
			}),
			undefined,
			3,
		],
		[
			"ValidationError",
			new ValidationError({
				status: 400,
				endpoint: "/v1/workouts",
				method: "GET",
			}),
			undefined,
			3,
		],
		[
			"HevyHttpError",
			new HevyHttpError("request failed", {
				status: 503,
				method: "GET",
				endpoint: "/v1/workouts",
				code: "HEVY_RETRY_EXHAUSTED",
			}),
			"HEVY_RETRY_EXHAUSTED",
			3,
		],
		[
			"execution cancellation",
			new HevyHttpError("request canceled", {
				method: "GET",
				endpoint: "/v1/workouts",
				code: "HEVY_REQUEST_ABORTED",
				outcome: "cancelled",
			}),
			"HEVY_REQUEST_ABORTED",
			4,
		],
		[
			"execution deadline",
			new HevyHttpError("request deadline exceeded", {
				method: "GET",
				endpoint: "/v1/workouts",
				code: "HEVY_DEADLINE_EXCEEDED",
				outcome: "deadline_exceeded",
			}),
			"HEVY_DEADLINE_EXCEEDED",
			4,
		],
		["generic", new Error("ordinary failure"), undefined, 2],
		["string", "ordinary string failure", undefined, 2],
		[
			"hostile",
			new Error(
				"hostile-fake-secret Authorization Bearer fake-token should be redacted",
			),
			undefined,
			2,
		],
	] as const;

	it("omits error_code from successful JSON", async () => {
		const io = streams();
		const code = await runCli({
			argv: ["workouts", "list", "--json"],
			env: { HEVY_API_KEY: "fake-key" },
			clientFactory: () =>
				mockClient(
					vi.fn().mockResolvedValue({
						page: 1,
						page_count: 1,
						workouts: [],
					}),
				),
			streams: io.streams,
		});

		expect(code).toBe(0);
		expect(JSON.parse(io.out)).not.toHaveProperty("error_code");
		expect(io.err).toBe("");
	});

	it.each(errorCases)(
		"keeps the accepted error_code and exit family for %s",
		async (_name, error, expectedErrorCode, expectedExitCode) => {
			const io = streams();
			const createOperations = await createOperationsSpy();
			const actualCreateOperations = createOperations.getMockImplementation();
			if (actualCreateOperations === undefined) {
				throw new Error("Missing createOperations test implementation");
			}
			const baseline = actualCreateOperations(mockClient(vi.fn()));
			createOperations.mockImplementationOnce(() => ({
				...baseline,
				workouts: {
					...baseline.workouts,
					list: {
						...baseline.workouts.list,
						effect: () => Effect.fail(error as never),
					},
				},
			}));
			const code = await runCli({
				argv: ["workouts", "list", "--json"],
				env: { HEVY_API_KEY: "fake-key" },
				clientFactory: () => mockClient(vi.fn()),
				streams: io.streams,
			});
			const diagnostic = JSON.parse(io.err) as {
				readonly error_code?: string;
			};

			expect(code).toBe(expectedExitCode);
			if (expectedErrorCode === undefined) {
				expect(diagnostic).not.toHaveProperty("error_code");
			} else {
				expect(diagnostic).toHaveProperty("error_code", expectedErrorCode);
			}
			expect(io.out).toBe("");
			expect(io.err).not.toContain("Effect");
			expect(io.err).not.toContain("Cause");
			expect(io.err).not.toContain("Fiber");
			if (_name === "hostile") {
				expect(io.err).not.toContain("hostile-fake-secret");
				expect(io.err).not.toContain("fake-token");
			}
		},
	);
});

import { describe, expect, it } from "vitest";
import {
	parseExerciseHistoryOptions,
	parseExerciseId,
	parseMeasurementDate,
	parsePagination,
	parseSearchMaxPages,
	parseSearchQuery,
	parseWeeks,
	parseWorkoutEventsOptions,
	parseWorkoutId,
	UsageError,
	requireMutationConfirmation,
	type CliArgs,
} from "./arguments.js";

const args = (
	options: CliArgs["options"] = {},
	positionals: string[] = [],
): CliArgs => ({ positionals, options });
const invalid = (callback: () => unknown, message: string) => {
	expect(callback).toThrow(UsageError);
	expect(callback).toThrow(message);
};

describe("CLI argument validation", () => {
	it("coerces pagination and preserves defaults", () => {
		expect(parsePagination(args())).toEqual({ page: 1, pageSize: 5 });
		expect(parsePagination(args({ page: "1", "page-size": "10" }))).toEqual({
			page: 1,
			pageSize: 10,
		});
	});

	it("rejects invalid and out-of-range pagination", () => {
		for (const page of ["0", "-1", "1.5", "nope"])
			invalid(
				() => parsePagination(args({ page })),
				"--page must be a positive integer",
			);
		for (const pageSize of ["0", "-1", "1.5", "nope", "11"])
			invalid(
				() => parsePagination(args({ "page-size": pageSize })),
				"--page-size must be a positive integer no greater than 10",
			);
	});

	it("validates event timestamps and maps options once", () => {
		expect(parseWorkoutEventsOptions(args())).toEqual({
			page: 1,
			pageSize: 5,
			since: "1970-01-01T00:00:00Z",
		});
		expect(
			parseWorkoutEventsOptions(
				args({
					page: "2",
					"page-size": "10",
					since: "2024-01-01T00:00:00+01:00",
				}),
			),
		).toEqual({ page: 2, pageSize: 10, since: "2024-01-01T00:00:00+01:00" });
		invalid(
			() => parseWorkoutEventsOptions(args({ since: "not-a-date" })),
			"--since must be an ISO timestamp",
		);
	});

	it("maps and validates optional exercise history dates", () => {
		expect(parseExerciseHistoryOptions()).toEqual({});
		expect(
			parseExerciseHistoryOptions(
				args({ "start-date": "2024-01-01T00:00:00+01:00" }),
			),
		).toEqual({ start_date: "2024-01-01T00:00:00+01:00" });
		expect(
			parseExerciseHistoryOptions(
				args({
					"start-date": "2024-01-01T00:00:00Z",
					"end-date": "2024-02-01T00:00:00Z",
				}),
			),
		).toEqual({
			start_date: "2024-01-01T00:00:00Z",
			end_date: "2024-02-01T00:00:00Z",
		});
		invalid(
			() => parseExerciseHistoryOptions(args({ "start-date": "2024-01-01" })),
			"--start-date must be an ISO timestamp",
		);
	});

	it("validates safe resource IDs and search terms", () => {
		expect(parseWorkoutId(" workout-1 ")).toBe("workout-1");
		expect(parseExerciseId(" exercise-1 ")).toBe("exercise-1");
		for (const value of [undefined, "", "  ", "a/b", "a?b"])
			invalid(() => parseWorkoutId(value), "Workout ID");
		for (const value of [undefined, "", "  ", "a/b", "a?b"])
			invalid(() => parseSearchQuery(value), "Search query");
		expect(parseSearchQuery(" Bench Press ")).toBe("bench press");
		expect(parseSearchMaxPages(args())).toBe(10);
		expect(parseSearchMaxPages(args({ "max-pages": "25" }))).toBe(25);
		invalid(
			() => parseSearchMaxPages(args({ "max-pages": "101" })),
			"--max-pages must be a positive integer no greater than 100",
		);
	});

	it("accepts real calendar dates and rejects impossible dates", () => {
		expect(parseMeasurementDate("2024-02-29")).toBe("2024-02-29");
		invalid(
			() => parseMeasurementDate("2023-02-29"),
			"Measurement date must be an ISO date",
		);
		invalid(
			() => parseMeasurementDate("2024-02-30"),
			"Measurement date must be an ISO date",
		);
	});

	it("coerces positive integer summary weeks", () => {
		expect(parseWeeks(args())).toBe(1);
		expect(parseWeeks(args({ weeks: "10" }))).toBe(10);
		for (const weeks of [
			"0",
			"-1",
			"1.5",
			"nope",
			"999999999999999999999",
			"521",
		])
			invalid(
				() => parseWeeks(args({ weeks })),
				"--weeks must be a positive integer no greater than 520",
			);
	});
});

describe("mutation confirmation", () => {
	it("requires an explicit true --yes flag", () => {
		expect(() =>
			requireMutationConfirmation(args({ yes: true })),
		).not.toThrow();
		for (const yes of [undefined, false])
			expect(() =>
				requireMutationConfirmation(args(yes === undefined ? {} : { yes })),
			).toThrow("Mutation requires --yes");
	});
});

import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { z } from "zod";
import {
	loadMutationInput,
	readDataSource,
	type DataSourceReader,
} from "./input.js";
import { UsageError } from "./arguments.js";
import {
	createRoutineInputSchema,
	routineFolderInputSchema,
	workoutInputSchema,
} from "@hevy-mcp/core/mutations";

const workout = {
	workout: {
		title: "Push",
		start_time: "2024-01-01T10:00:00Z",
		end_time: "2024-01-01T11:00:00Z",
		exercises: [
			{
				exercise_template_id: "exercise-1",
				sets: [{ type: "normal", weight_kg: 50, reps: 5 }],
			},
		],
	},
};

describe("mutation input sources", () => {
	it("loads equivalent inline, file, and stdin JSON", async () => {
		const inline = await loadMutationInput(
			JSON.stringify(workout),
			workoutInputSchema,
		);
		const directory = await mkdtemp(join(tmpdir(), "hevy-cli-"));
		const path = join(directory, "workout.json");
		try {
			await writeFile(path, JSON.stringify(workout), "utf8");
			const file = await loadMutationInput(
				`@${path}`,
				workoutInputSchema,
				readDataSource,
			);
			const stdin = await loadMutationInput(
				"@-",
				workoutInputSchema,
				(source) => {
					expect(source).toBe("-");
					return Promise.resolve(JSON.stringify(workout));
				},
			);
			expect(file).toEqual(inline);
			expect(stdin).toEqual(inline);
		} finally {
			await rm(directory, { recursive: true, force: true });
		}
	});

	it("reports source, JSON, and schema failures as usage errors", async () => {
		const reader: DataSourceReader = () => Promise.reject(new Error("missing"));
		await expect(
			loadMutationInput("@", workoutInputSchema, reader),
		).rejects.toThrow(new UsageError("--data source is required after @"));
		await expect(
			loadMutationInput("@missing", workoutInputSchema, reader),
		).rejects.toThrow(new UsageError('Unable to read --data source "missing"'));
		await expect(loadMutationInput("{", workoutInputSchema)).rejects.toThrow(
			new UsageError("--data must contain valid JSON"),
		);
		await expect(
			loadMutationInput(
				JSON.stringify({ outer: { inner: 1 } }),
				z.strictObject({ outer: z.strictObject({ inner: z.string() }) }),
			),
		).rejects.toThrow(/--data\.outer\.inner/);
	});

	it.each([
		[
			"top-level",
			{ ...workout, extra: true },
			workoutInputSchema,
			/--data.*"extra"/,
		],
		[
			"wrapperless",
			{ ...workout.workout, extra: true },
			workoutInputSchema.shape.workout,
			/--data.*"extra"/,
		],
		[
			"exercise",
			{
				workout: {
					...workout.workout,
					exercises: [{ ...workout.workout.exercises[0], extra: true }],
				},
			},
			workoutInputSchema,
			/--data\.workout\.exercises\.0.*"extra"/,
		],
		[
			"legacy weight alias",
			{
				workout: {
					...workout.workout,
					exercises: [
						{
							...workout.workout.exercises[0],
							sets: [{ type: "normal", weightKg: 50 }],
						},
					],
				},
			},
			workoutInputSchema,
			/--data\.workout\.exercises\.0\.sets\.0.*"weightKg"/,
		],
		[
			"legacy routine field",
			{
				routine: {
					title: "Routine",
					exercises: [
						{
							exercise_template_id: "exercise-1",
							sets: [{ type: "normal", rep_range: { start: 5, extra: true } }],
						},
					],
				},
			},
			createRoutineInputSchema,
			/--data\.routine\.exercises\.0\.sets\.0\.rep_range.*"extra"/,
		],
	] as const)(
		"rejects unknown %s keys",
		async (_name, value, schema, expectedPattern) => {
			await expect(
				loadMutationInput<unknown>(
					JSON.stringify(value),
					schema as z.ZodType<unknown>,
				),
			).rejects.toThrow(expectedPattern);
		},
	);

	it("uses strict API-shaped folder schemas", async () => {
		await expect(
			loadMutationInput(
				JSON.stringify({ routine_folder: { title: "Strength", extra: true } }),
				routineFolderInputSchema,
			),
		).rejects.toThrow(/--data.*extra/);
		await expect(
			loadMutationInput(
				JSON.stringify({ name: "Strength" }),
				routineFolderInputSchema,
			),
		).rejects.toThrow(/--data/);
	});
});

