type OperationSafety = "read" | "non-idempotent-write" | "idempotent-write";

function operation<Id extends string, Safety extends OperationSafety, T>(
	id: Id,
	safety: Safety,
	value: T,
) {
	const effect = vi.fn(() => Effect.succeed(value));
	return {
		descriptor: { id, safety },
		effect,
		execute: vi.fn(),
	};
}

