const [requirementsArg, testFile, ...vitestArgs] = process.argv.slice(2);
if (!requirementsArg || !testFile) {
	throw new Error(
		"run-live-vitest.mjs requires an environment requirement list and test file",
	);
}

try {
	loadOptionalEnvFile();
} catch (error) {
	console.error(
		error instanceof Error ? error.message : "Unable to load .env.",
	);
	process.exit(1);
}

for (const requirement of requirementsArg.split(",")) {
	const [name, expected] = requirement.split("=", 2);
	const actual = process.env[name];
	if (!actual?.trim() || (expected !== undefined && actual !== expected)) {
		console.error(
			`${name}${expected ? `=${expected}` : ""} is required for ${testFile}; no live tests were started.`,
		);
		process.exit(1);
	}
}

const result = spawnSync(
	process.execPath,
	["node_modules/vitest/vitest.mjs", "run", testFile, ...vitestArgs],
	{
		stdio: "inherit",
		env: process.env,
	},
);

if (result.error) throw result.error;
process.exit(result.status ?? 1);

import { readFileSync } from "node:fs";
import { parseEnv } from "node:util";

const ENV_ENTRY_PATTERN = /^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=(.*)$/;

/**
 * Load the optional dotenv file for a lane without replacing explicit
 * process environment values.
 *
 * Native `--env-file-if-exists` is intentionally not used as the only
 * boundary here: it does not provide a useful failure signal for malformed
 * input. A lane must fail closed instead of silently falling back to another
 * environment.
 */
export function loadOptionalEnvFile(path = ".env") {
	let source;
	try {
		source = readFileSync(path, "utf8");
	} catch (error) {
		if (error instanceof Error && "code" in error && error.code === "ENOENT")
			return;
		throw new Error(`Unable to read ${path}.`);
	}

	for (const line of source.split(/\r?\n/u)) {
		const trimmed = line.trim();
		if (trimmed === "" || trimmed.startsWith("#")) continue;
		const match = ENV_ENTRY_PATTERN.exec(line);
		if (match === null) {
			throw new Error(`Malformed ${path}.`);
		}
		const value = match[2].trim();
		if (
			(value.startsWith('"') && !value.endsWith('"')) ||
			(value.startsWith("'") && !value.endsWith("'"))
		) {
			throw new Error(`Malformed ${path}.`);
		}
	}

	let entries;
	try {
		entries = parseEnv(source);
	} catch {
		throw new Error(`Malformed ${path}.`);
	}

	for (const [name, value] of Object.entries(entries)) {
		if (process.env[name] === undefined) process.env[name] = value;
	}
}

