	liveJson("live-routines-list", ["routines", "list", "--page-size", "1", "--json"], "routines");
	liveJson("live-measurements-list", ["measurements", "list", "--page-size", "1", "--json"], "body_measurements");
	liveJson("live-summary", ["summary", "--weeks", "1", "--json"], "workout_count");
	liveJson("live-events", ["workouts", "events", "--page-size", "1", "--json"], "events");
	liveJson("live-search", ["exercises", "search", "bench", "--max-pages", "1", "--json"], "matches");

	const firstWorkoutId = workouts?.workouts?.[0]?.id;
